ts-prim-001.example:
```ts
let lower: string = 'hello';   // ✅ the primitive — what you want
console.log(lower.toUpperCase());

function shout(s: string) { return s.toUpperCase(); }
const wrapped: String = new String('hi'); // the wrapper OBJECT type
// @ts-expect-error a String object is not assignable to the string primitive
shout(wrapped);
```

ts-prim-002.example:
```ts
const a: string = 'hi';
const b: number = 42;     // ints and floats are both `number`
const c: boolean = true;

// The type name matches what typeof reports:
console.log(typeof a, typeof b, typeof c); // 'string' 'number' 'boolean'
```

ts-prim-003.example:
```ts
let myName = 'Alice'; // inferred as string — no annotation needed
console.log(myName.toUpperCase());

// @ts-expect-error number is not assignable to the inferred type string
myName = 42;

const exact = 'Alice'; // const infers the literal type "Alice"
const widened = exact; // still "Alice" here
console.log(exact, widened);
```

ts-prim-mcq-001.example:
```ts
let value: any = 'hello';
value.foo.bar();      // no error — any disables all checking
value = 42;
value();              // calling a number — still no compile error
const n: number = value; // any flows into any type unchecked

// Safer alternative: unknown forces you to narrow first.
let u: unknown = 'hi';
// @ts-expect-error 'u' is of type 'unknown' — must narrow before use
u.toUpperCase();
if (typeof u === 'string') u.toUpperCase(); // ok
console.log(n);
```

ts-prim-004.example:
```ts
// Explicit types satisfy noImplicitAny:
function double(x: number) { return x * 2; }

// @ts-expect-error noImplicitAny: parameter 'x' implicitly has an 'any' type
function echo(x) { return x; }

console.log(double(2), echo('still works at runtime'));
```

ts-prim-mcq-002.example:
```ts
const req = { method: 'GET' };
const m: string = req.method; // inferred type is string (widened, mutable prop)

// @ts-expect-error string is not assignable to the literal type "GET"
const lit: 'GET' = req.method;
console.log(m);
```

ts-prim-005.example:
```ts
const req = { method: 'GET' } as const;
const m: 'GET' = req.method; // literal "GET", thanks to as const

// @ts-expect-error cannot assign to 'method' — it is a read-only property
req.method = 'POST';
console.log(m);
```

ts-prim-mcq-003.example:
```ts
function printText(s: string, alignment: 'left' | 'right' | 'center') {}

let a = 'left'; // widened to string
// @ts-expect-error string is not assignable to the literal union
printText('Hello', a);

const b = 'left'; // inferred as the literal "left"
printText('Hello', b);          // ✅ ok
printText('Hello', a as 'left'); // ✅ also ok via assertion
```

ts-prim-006.example:
```ts
function printLen(x: string | null) {
  // @ts-expect-error 'x' is possibly 'null' (strictNullChecks on)
  console.log(x.length);

  if (x !== null) console.log(x.length); // ✅ narrowed to string
  console.log(x?.length ?? 0);           // ✅ optional chaining + default
}
printLen('hello');
```

ts-prim-mcq-004.example:
```ts
function liveDangerously(x?: number | null) {
  // `!` removes null/undefined from the type at COMPILE time only.
  console.log(x!.toFixed()); // crashes at runtime if x really is null/undefined
}
liveDangerously(42); // fine
// liveDangerously() — would throw at runtime despite compiling cleanly
```

ts-prim-007.example:
```ts
const big1: bigint = BigInt(100);
const big2 = 100n;            // literal form
console.log(big1 === big2);   // true — same numeric value

const s1: symbol = Symbol('id');
const s2: symbol = Symbol('id');
console.log(s1 === s2);       // false — every Symbol() is unique
console.log(Symbol.for('k') === Symbol.for('k')); // true — shared registry
```
